    DailyLessonDef(
      id: "course-y1-math-w6-d4",
      dayNumber: 4,
      titleEn: "Reading: Su Myat's Snack Jar",
      titleMy: "စာဖတ်ခြင်း - စုမြတ်၏ သရေစာဗူး",
      kind: LessonKind.reading,
